def copyedit_prose(text):
    # A finite authored copy-edit list: no SQL, fixture values or meaningful spaces
    # inside expected string results are transformed.
    if text != text.strip():
        return text
    for phrase in sorted(set(COPY_EDITS.strip().splitlines()),key=len,reverse=True):
        text=text.replace(phrase.replace(' ',''),phrase)
    import re
    text=re.sub(r'(?<=[가-힣])(?=[A-Za-z0-9])',' ',text)
    text=re.sub(r'([0-9])((?:행|개|일|월|년|시간|분|문자|그룹))(?=(?:모두|이상|미만|결과))',r'\1\2 ',text)
    text=text.replace('비 NULL','비NULL')
    return text

